    'handlers.mjs': handlerEntry(prepared.plan), 'RUN.md': runbook(folder, prepared.plan) };
  for (const [name, content] of Object.entries(files))
    await writeFile(join(folder, name), content, { flag: 'wx', mode: 0o600 });
