/** Run the original Xero workspace, source capture, draft/read operations and return recovery. */
export async function startXeroAccountingWorkspace({
  connectionsFile,selectionDirectory,env=process.env,allowLoopback=false,lookup,agent,fetchImpl,timeoutMs,signal,...accountingOptions
}={}) {
  need(accountingOptions.xeroClient===undefined,'XERO_OAUTH_CLIENT_OVERRIDE','The reviewed tenant supplies this native accounting client.',400);
  const environment={...env};
  const registry=await openOAuthConnectionRegistry({connections:await readOAuthHostConnections(connectionsFile),
    env:environment,allowLoopback,...(lookup?{lookup}:{}),...(agent?{agent}:{})});
  let owner,accounting,closing;
  const close=()=>{
    if(!closing)closing=(async()=>{
      const errors=[];
      try{await accounting?.close();}catch(error){errors.push(error);}
      try{await owner?.close();}catch(error){errors.push(error);}
      try{await registry.close();}catch(error){errors.push(error);}
      if(errors.length)throw Object.assign(new AggregateError(errors,'The managed Xero accounting owner did not close cleanly.'),{code:'XERO_OAUTH_CLOSE_FAILED'});
    })();
    return closing;
  };
  try{
    const selection=await readXeroSelection(selectionDirectory);
    owner=await openXeroOAuthClient({registry,selection,env:environment,allowLoopback,signal,
      ...(lookup?{lookup}:{}),...(agent?{agent}:{}),...(fetchImpl?{fetchImpl}:{}),...(timeoutMs===undefined?{}:{timeoutMs})});
    const {startAccountingWorkspace}=await import('../../merchant-settlement-accounting/workspace/server.mjs');
    accounting=await startAccountingWorkspace({...accountingOptions,xeroClient:owner.client});
    return Object.freeze({accounting,selection:xeroSelectionSummary(selection),
      connectionStatus:()=>registry.status(selection.alias),providerStatus:owner.snapshot,close});
  }catch(error){await close().catch(()=>{});throw error;}
}

// MIT. The CLI and browser operate the same original retained OData workspace.
import { readFile } from 'node:fs/promises';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { openODataWorkspace } from './workspace.mjs';
import { writeNew, formatted } from './state.mjs';

const HELP=`OData source and merchant workspace

node cli.mjs --workspace DIRECTORY COMMAND [options]

  init | status
  serve [--port 8797] [--live-service SERVICE]
  connect --url SERVICE --name NAME [--id ID] [--auth-env VARIABLE]
  schema --connection ID
  refresh --connection ID
  plan --connection ID --input QUERY.json [--name NAME] [--id ID]
  review-plan --id ID --note TEXT
  capture --plan ID [--label NAME] [--pages 10000]
  resume --id EDITION [--pages 10000]
  rows --id EDITION [--out FILE]
  review --id EDITION --decision accept|needs-work --note TEXT
  compare --before EDITION --after EDITION [--out FILE]
  semantics --id EDITION [--fields A,B] [--out FILE]
  export --id EDITION [--expected-semantics SHA256] [--name NAME] [--fields A,B] [--payment FILE --origin URL --path /data]
  query --export ID [--query 'limit=20&sort=ID']
  backup --out FILE
  restore --input FILE
  merchant prepare --export ID --release ID [--runtime FILE]
  merchant status
  merchant activate --id ID --expect GENERATION --reason TEXT
  merchant rollback [--to ID] --expect GENERATION --reason TEXT
  merchant run --expect GENERATION
  live prepare --input PROFILE.json
  live status | detail --id SERVICE
  live run --id SERVICE
  live buyer --id SERVICE --intent STABLE_INTENT [--received RECEIPT]
  live receive --id SERVICE --response ORIGINAL_RESPONSE.json
  live collections --id SERVICE
  live collection --id SERVICE --collection COLLECTION
  live collect --id SERVICE --collection COLLECTION --input SELECTION.json
  live collection-rows --id SERVICE --collection COLLECTION [--offset 0 --limit 100]
  live collection-file --id SERVICE --collection COLLECTION --file NAME --out FILE
  live restore-collection --id SERVICE --collection COLLECTION --input SOURCE.json --sha SHA256

Plans use declared entity properties and typed filter clauses. Imports follow the
original nextLink and save every page before continuing. --pages sets the work
per invocation; unfinished imports retain their original continuation for resume.
Provider credentials are read from the named environment variable.
`;
function parse(args){
  const options={},words=[];
  for(let i=0;i<args.length;i++){
    if(!args[i].startsWith('--')){words.push(args[i]);continue;}
    const key=args[i].slice(2);if(Object.hasOwn(options,key)||!args[i+1]||args[i+1].startsWith('--'))throw new Error('Option --'+key+' needs one value.');
    options[key]=args[++i];
  }
